@Test
    public void testCreateNewIfExpired() throws Exception {
        HttpConnectionFactory connFactory = Mockito.mock(HttpConnectionFactory.class);

        HttpConnection conn1 = Mockito.mock(HttpConnection.class);
        Mockito.when(connFactory.create(Mockito.eq("somehost"))).thenReturn(conn1);

        LocalConnPool pool = new LocalConnPool(connFactory, 2, 2);

        Future<LocalPoolEntry> future1 = pool.lease("somehost", null);
        LocalPoolEntry entry1 = future1.get(1, TimeUnit.SECONDS);
        Assert.assertNotNull(entry1);

        Mockito.verify(connFactory, Mockito.times(1)).create(Mockito.eq("somehost"));

        entry1.updateExpiry(1, TimeUnit.MILLISECONDS);
        pool.release(entry1, true);

        Thread.sleep(200L);

        Future<LocalPoolEntry> future2 = pool.lease("somehost", null);
        LocalPoolEntry entry2 = future2.get(1, TimeUnit.SECONDS);
        Assert.assertNotNull(entry2);

        Mockito.verify(connFactory, Mockito.times(2)).create(Mockito.eq("somehost"));

        PoolStats totals = pool.getTotalStats();
        Assert.assertEquals(0, totals.getAvailable());
        Assert.assertEquals(1, totals.getLeased());
        PoolStats stats = pool.getStats("somehost");
        Assert.assertEquals(0, stats.getAvailable());
        Assert.assertEquals(1, stats.getLeased());
    }

@Deployment
  public void testTerminateInSubProcessWithBoundary() throws Exception {
    Date startTime = new Date();

    // Test terminating process via boundary timer

    ProcessInstance pi = runtimeService.startProcessInstanceByKey("terminateEndEventWithBoundary");

    assertEquals(3, taskService.createTaskQuery().processInstanceId(pi.getId()).count());

    // Set clock time to '1 hour and 5 seconds' ahead to fire timer
    processEngineConfiguration.getClock().setCurrentTime(new Date(startTime.getTime() + ((60 * 60 * 1000) + 5000)));
    waitForJobExecutorToProcessAllJobs(5000L, 25L);

    // timer has fired
    assertEquals(0L, managementService.createJobQuery().count());

    assertProcessEnded(pi.getId());

    assertHistoricProcessInstanceDeleteReason(pi, DeleteReason.TERMINATE_END_EVENT);
    assertHistoricTasksDeleteReason(pi, DeleteReason.TERMINATE_END_EVENT, "check before normal end");
    assertHistoricActivitiesDeleteReason(pi, DeleteReason.TERMINATE_END_EVENT, "outerTask");

    // Test terminating subprocess

    pi = runtimeService.startProcessInstanceByKey("terminateEndEventWithBoundary");

    assertEquals(3, taskService.createTaskQuery().processInstanceId(pi.getId()).count());

    // a job for boundary event timer should exist 
    assertEquals(1L, managementService.createTimerJobQuery().count());

    // Complete sub process task that leads to a terminate end event
    Task task = taskService.createTaskQuery().processInstanceId(pi.getId()).taskDefinitionKey("preTermInnerTask").singleResult();
    taskService.complete(task.getId());

    // 'preEndInnerTask' task in subprocess should have been terminated, only outerTask should exist
    assertEquals(1, taskService.createTaskQuery().processInstanceId(pi.getId()).count());

    // job for boundary event timer should have been removed  
    assertEquals(0L, managementService.createTimerJobQuery().count());

    // complete outerTask
    task = taskService.createTaskQuery().processInstanceId(pi.getId()).taskDefinitionKey("outerTask").singleResult();
    taskService.complete(task.getId());

    assertProcessEnded(pi.getId());
    assertHistoricProcessInstanceDetails(pi);
  }

@Test
  public void runReconstructionLog() throws Exception {

    byte[] family = Bytes.toBytes("column");
    HColumnDescriptor hcd = new HColumnDescriptor(family);
    HTableDescriptor htd = new HTableDescriptor(TABLE);
    htd.addFamily(hcd);
    HRegionInfo info = new HRegionInfo(htd, null, null, false);
    Path oldLogDir = new Path(this.dir, HConstants.HREGION_OLDLOGDIR_NAME);
    HLog log = new HLog(cluster.getFileSystem(),
        this.dir, oldLogDir, conf, null);
    HRegion region = new HRegion(dir, log,
        cluster.getFileSystem(),conf, info, null);
    List<KeyValue> result = new ArrayList<KeyValue>();

    // Empty set to get all columns
    NavigableSet<byte[]> qualifiers = new ConcurrentSkipListSet<byte[]>(Bytes.BYTES_COMPARATOR);

    final byte[] tableName = Bytes.toBytes(TABLE);
    final byte[] rowName = tableName;
    final byte[] regionName = info.getRegionName();

    // Add 10 000 edits to HLog on the good family
    for (int j = 0; j < TOTAL_EDITS; j++) {
      byte[] qualifier = Bytes.toBytes(Integer.toString(j));
      byte[] column = Bytes.toBytes("column:" + Integer.toString(j));
      WALEdit edit = new WALEdit();
      edit.add(new KeyValue(rowName, family, qualifier,
          System.currentTimeMillis(), column));
      log.append(info, tableName, edit,
          System.currentTimeMillis());
    }
    // Add a cache flush, shouldn't have any effect
    long logSeqId = log.startCacheFlush();
    log.completeCacheFlush(regionName, tableName, logSeqId, info.isMetaRegion());

    // Add an edit to another family, should be skipped.
    WALEdit edit = new WALEdit();
    edit.add(new KeyValue(rowName, Bytes.toBytes("another family"), rowName,
          System.currentTimeMillis(), rowName));
    log.append(info, tableName, edit,
          System.currentTimeMillis());
    log.sync();

    // TODO dont close the file here.
    log.close();

    List<Path> splits =
        HLog.splitLog(new Path(conf.get(HConstants.HBASE_DIR)),
            this.dir, oldLogDir, cluster.getFileSystem(), conf);

    // Split should generate only 1 file since there's only 1 region
    assertEquals(1, splits.size());

    // Make sure the file exists
    assertTrue(cluster.getFileSystem().exists(splits.get(0)));

    // This will run the log reconstruction
    Store store = new Store(dir, region, hcd, cluster.getFileSystem(),
        splits.get(0), conf, null);

    Get get = new Get(rowName);
    store.get(get, qualifiers, result);
    // Make sure we only see the good edits
    assertEquals(TOTAL_EDITS, result.size());
  }
